let path = nativePath;
if (isUnified || isTag) {
  // Map unified mailbox folders to /unified/*, virtual tag folders to /tag/*
  id = isUnified ? `unified:/${nativePath}` : `tag:/${path.substring(5)}`;
  path = isUnified ? `/unified${nativePath}` : `/tag${path.substring(5)}`;
}

